X=np.column_stack([np.ones_like(x),x,v,t]); c,_,_,_=np.linalg.lstsq(X,y,rcond=None); r=y-X@c
for name,a in [('t',t),('x',x),('v',v)]:
    qs=np.quantile(a,np.linspace(0,1,7))
    out=[]
    for i in range(6):
        m=(a>=qs[i])&(a<=qs[i+1]); out.append(round(r[m].mean(),3))
    print(name,out)
# residual vs x*v etc
for name,a in [('xv',x*v),('x2',x**2),('v2',v**2),('tx',t*x),('tv',t*v)]:
    print(name, np.corrcoef(a,r)[0,1].round(3))

